def get_shape_input():
    """Ask the user for the type of geometric shape and validate the input."""
    while True:
        shape_type = input("Enter the type of geometric shape (rectangle, triangle, circle): ").lower()
        if shape_type in ['rectangle', 'triangle', 'circle']:
            return shape_type
        else:
            print("Invalid input. Please enter 'rectangle', 'triangle', or 'circle'.")

def calculate_shape_properties(shape_type, width, height):
    """Calculate the area and perimeter of the given geometric shape."""
    if shape_type == 'rectangle':
        area = width * height
        perimeter = 2 * (width + height)
    elif shape_type == 'triangle':
        area = 0.5 * width * height
        perimeter = width + height
    elif shape_type == 'circle':
        area = 3.14159 * (width / 2) ** 2
        perimeter = 2 * 3.14159 * width / 2
    else:
        raise ValueError("Invalid shape type. Please enter 'rectangle', 'triangle', or 'circle'.")

    return area, perimeter

def main():
    shape_type = get_shape_input()
    width = float(input("Enter the width: "))
    height = float(input("Enter the height (for rectangle and triangle): "))

    area, perimeter = calculate_shape_properties(shape_type, width, height)

    print(f"area: {area:.2f}, perimeter: {perimeter:.2f}")

if __name__ == "__main__":
    main()
```

This script defines three functions: `get_shape_input()` to validate and get the user input, `calculate_shape_properties()` to calculate the area and perimeter of the given shape, and `main()` to call the other two functions and display the results.
